/// <reference types="@cloudflare/workers-types" />
/**
 * Cloudflare Worker entry point — auto-generated by vinext deploy.
 * Edit freely or delete to regenerate on next deploy.
 *
 * For apps without image optimization, you can use vinext/server/app-router-entry
 * directly in wrangler.jsonc: "main": "vinext/server/app-router-entry"
 */
import * as Sentry from "@sentry/cloudflare";
import {
  handleImageOptimization,
  DEFAULT_DEVICE_SIZES,
  DEFAULT_IMAGE_SIZES,
} from "vinext/server/image-optimization";
import type { ImageConfig } from "vinext/server/image-optimization";
import handler from "vinext/server/app-router-entry";
import { runWithDb } from "../src/lib/db-client-lazy";
import { wrapFetch } from "./lib/otel";
import {
  applyRuntimeAuthEnv,
  getHyperdriveConnectionString,
  getSentryOptions,
} from "./runtime-env";

interface Env {
  ASSETS: Fetcher;
  IMAGES: {
    input(stream: ReadableStream): {
      transform(options: Record<string, unknown>): {
        output(options: {
          format: string;
          quality: number;
        }): Promise<{ response(): Response }>;
      };
    };
  };
  HYPERDRIVE: { connectionString: string };
  GATEWAY_URL?: string;
  NUDGE_SHARED_SECRET?: string;
  [key: string]: unknown;
}

interface ExecutionContext {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
}

// Image security config. SVG sources with .svg extension auto-skip the
// optimization endpoint on the client side (served directly, no proxy).
// To route SVGs through the optimizer (with security headers), set
// dangerouslyAllowSVG: true in next.config.js and uncomment below:
// const imageConfig: ImageConfig = { dangerouslyAllowSVG: true };

export default Sentry.withSentry(
  (env: Record<string, unknown> | undefined) => getSentryOptions(env),
  {
    // Autonomous backlog driver — runs on the Cron trigger in wrangler.jsonc.
    // Dispatches ready work items up to the concurrency cap + a daily rate
    // limit, rotating across agents. Gated on BOB_AUTO_DRAIN_ENABLED so it can
    // be turned off with a var change, no redeploy.
    scheduled: async (
      _event: unknown,
      rawEnv: Record<string, unknown> | undefined,
      ctx: ExecutionContext,
    ): Promise<void> => {
      const runtimeEnv = (rawEnv ?? {}) as Env;
      const autoDrainOn =
        String(runtimeEnv.BOB_AUTO_DRAIN_ENABLED ?? "") === "true";
      // Review is done by a runner agent (dispatchReviewSession), not a model
      // API — so this no longer requires ANTHROPIC_API_KEY.
      const autoMergeOn =
        String(runtimeEnv.BOB_AUTO_MERGE_ENABLED ?? "") === "true";
      // Keep the Linear backlog fresh server-side (default on) — the sync was
      // webhook-only, so new Linear tasks stopped reaching Bob when the webhook
      // went quiet. This pull backfills + maintains. Gated to ~every 15 min to
      // stay well under Linear's API rate limit.
      const syncLinearOn =
        String((runtimeEnv as any).BOB_AUTO_SYNC_LINEAR_ENABLED ?? "true") !== "false";
      const scheduledTime =
        typeof (_event as any)?.scheduledTime === "number"
          ? (_event as any).scheduledTime
          : Date.now();
      const syncLinearDue = Math.floor(scheduledTime / 60_000) % 15 === 0;
      if (!autoDrainOn && !autoMergeOn && !syncLinearOn) {
        return;
      }
      const concurrency = Number(runtimeEnv.BOB_AUTO_DRAIN_CONCURRENCY ?? 4);
      const dailyCap = Number(runtimeEnv.BOB_AUTO_DRAIN_DAILY_CAP ?? 20);
      const nudgeSecret =
        runtimeEnv.NUDGE_SHARED_SECRET ?? process.env.NUDGE_SHARED_SECRET;
      if (nudgeSecret) {
        (globalThis as any).NUDGE_SHARED_SECRET = nudgeSecret;
      }
      const { connectionString, isHyperdrive } =
        getHyperdriveConnectionString(runtimeEnv);
      const work = runWithDb(connectionString, isHyperdrive, async () => {
        // 0. Keep the Linear backlog in sync (backfill + ongoing). Runs
        // server-side with full DB access — no user session needed, which is
        // why the cron is the right home for this (the RPC requires a browser
        // session). Imports open Linear issues as work items; a Linear "Todo"
        // maps to Bob "todo", which auto-drain then dispatches.
        if (syncLinearOn && syncLinearDue) {
          try {
            const { db } = await import("@bob/db/client");
            const { syncLinearProjects } = await import(
              "@bob/api/handlers/linearSetup"
            );
            const { workspaceIntegrations, workspaceMembers } = await import(
              "@bob/db/schema"
            );
            const { eq, and, asc } = await import("@bob/db");
            const integrations = await db.query.workspaceIntegrations.findMany({
              where: and(
                eq(workspaceIntegrations.provider, "linear"),
                eq(workspaceIntegrations.enabled, true),
              ),
            });
            for (const integ of integrations) {
              const owner = await db.query.workspaceMembers.findFirst({
                where: eq(workspaceMembers.workspaceId, integ.workspaceId),
                columns: { userId: true },
                orderBy: [asc(workspaceMembers.joinedAt)],
              });
              if (!owner) continue;
              const r = await syncLinearProjects(
                { db, userId: owner.userId },
                { workspaceId: integ.workspaceId, importIssues: true },
              );
              console.log(
                `[linear-sync] ws=${integ.workspaceId} projectsCreated=${r.projectsCreated} projectsExisting=${r.projectsExisting} issuesImported=${r.issuesImported}` +
                  (r.issuesTruncated ? " (issues truncated)" : ""),
              );
            }
          } catch (err) {
            console.error("[linear-sync] failed:", err);
          }
        }
        // 1. Dispatch backlog work.
        if (autoDrainOn) {
          // 1a. Reap zombie sessions FIRST so freed slots are usable this tick.
          // A session whose runner died lingers in an active status forever and
          // permanently consumes an autoDrain slot; enough of them starve the
          // whole pipeline ("no free slots"). Gated so it can be disabled with a
          // var change, no redeploy. Best-effort — a reaper failure must not
          // block dispatch, so it's caught and logged, never thrown.
          if (String(runtimeEnv.BOB_SESSION_REAP_ENABLED ?? "true") !== "false") {
            try {
              const { reapStuckSessions } = await import(
                "@bob/api/handlers/reapStuckSessions"
              );
              const reap = await reapStuckSessions({
                leaseGraceMs: runtimeEnv.BOB_SESSION_REAP_LEASE_GRACE_MS
                  ? Number(runtimeEnv.BOB_SESSION_REAP_LEASE_GRACE_MS)
                  : undefined,
                hardTimeoutMs: runtimeEnv.BOB_SESSION_REAP_HARD_TIMEOUT_MS
                  ? Number(runtimeEnv.BOB_SESSION_REAP_HARD_TIMEOUT_MS)
                  : undefined,
              });
              if (reap.reaped > 0) {
                console.log(
                  `[session-reap] reaped=${reap.reaped} sessions=${reap.sessions
                    .map((s) => `${s.id.slice(0, 8)}:${s.status}`)
                    .join(",")}`,
                );
              }
            } catch (err) {
              console.error("[session-reap] failed:", err);
            }
          }

          const { autoDrainBacklog } = await import(
            "@bob/api/handlers/autoDrain"
          );
          try {
          const result = await autoDrainBacklog({ concurrency, dailyCap });
          console.log(
            `[auto-drain] dispatched=${result.dispatched} running=${result.running} today=${result.dispatchedToday}` +
              (result.reason ? ` reason="${result.reason}"` : "") +
              (result.items.length
                ? ` items=${result.items.map((i) => `${i.identifier}:${i.agentType}`).join(",")}`
                : ""),
          );
        } catch (error) {
          const { buildFailurePayload, getFailureSentryTags } = await import(
            "@bob/observability/failures"
          );
          const failure = {
            surface: "job" as const,
            operation: "auto_drain_backlog",
            error,
            alertId: "auto-drain-failure",
            tenant: runtimeEnv.BOB_TENANT_ID
              ? { tenantId: String(runtimeEnv.BOB_TENANT_ID) }
              : undefined,
          };
          console.error(
            "[auto-drain] failed",
            buildFailurePayload(failure),
          );
          Sentry.withScope((scope) => {
            scope.setLevel("error");
            scope.setTags(getFailureSentryTags(failure));
            scope.setContext("failure", buildFailurePayload(failure));
            Sentry.captureException(
              error instanceof Error ? error : new Error(String(error)),
            );
          });
          throw error;
        }
        }
        // 2. Review + auto-merge the PRs those tasks produced.
        if (autoMergeOn) {
          const { autoReviewAndMerge } = await import(
            "@bob/api/handlers/autoMergeReview"
          );
          const r = await autoReviewAndMerge({
            maxPerRun: Number(runtimeEnv.BOB_AUTO_MERGE_MAX_PER_RUN ?? 5),
            reviewAgentType:
              (runtimeEnv.BOB_AUTO_MERGE_REVIEW_AGENT as string | undefined) ??
              "codex",
            dryRun: String(runtimeEnv.BOB_AUTO_MERGE_DRY_RUN ?? "") === "true",
            forgejoToken: runtimeEnv.BOB_FORGEJO_TOKEN as string | undefined,
            forgejoInstanceUrl:
              (runtimeEnv.BOB_FORGEJO_INSTANCE_URL as string | undefined) ??
              "https://git.forgegraf.com",
            // Dedicated reviewer bot (separate identity — the git host rejects
            // self-reviews on the author's own PRs).
            reviewForgejoToken: runtimeEnv.BOB_REVIEW_FORGEJO_TOKEN as
              | string
              | undefined,
            reviewerLogin:
              (runtimeEnv.BOB_AUTO_MERGE_REVIEWER_LOGIN as string | undefined) ??
              "bob-reviewer",
            // Auto-repair: send a runner agent to fix PRs stuck on CI/conflict/
            // requested-changes so the review→repair→merge loop converges.
            repairEnabled:
              String(runtimeEnv.BOB_AUTO_REPAIR_ENABLED ?? "") === "true",
            repairAgentType:
              (runtimeEnv.BOB_AUTO_REPAIR_AGENT as string | undefined) ?? "codex",
            maxRepairsPerRun: Number(runtimeEnv.BOB_AUTO_REPAIR_MAX_PER_RUN ?? 3),
            maxRepairAttemptsPerPr: Number(
              runtimeEnv.BOB_AUTO_REPAIR_MAX_ATTEMPTS_PER_PR ?? 3,
            ),
          });
          console.log(
            `[auto-merge] scanned=${r.scanned} reviewed=${r.reviewed} repaired=${r.repaired} merged=${r.merged} skipped=${r.skipped}` +
              (r.authFailures ? ` authFailures=${r.authFailures}` : "") +
              (r.items.length
                ? ` items=${r.items.map((i) => `${i.pr}:${i.action}${i.reason ? `(${i.reason})` : ""}`).join(", ")}`
                : ""),
          );
          // Silent-dead-loop guard: a revoked/expired shared Forgejo token makes
          // EVERY PR 401 and get counted as an ordinary "skip", so the counters
          // look healthy (scanned=N skipped=N) while the review→repair→merge loop
          // is fully dead — exactly the 2026-07-29 outage that went unnoticed for
          // ~23h. Escalate loudly when auth failures dominate a run that produced
          // no forward progress. Threshold (not >0) so a single expired per-user
          // OAuth connection doesn't page.
          const authDominates =
            r.authFailures > 0 &&
            r.reviewed + r.repaired + r.merged === 0 &&
            r.authFailures >= Math.max(3, Math.floor(r.scanned / 2));
          if (authDominates) {
            const { buildFailurePayload, getFailureSentryTags } = await import(
              "@bob/observability/failures"
            );
            const failure = {
              surface: "job" as const,
              operation: "auto_merge_review",
              error: new Error(
                `auto-merge git-host auth failing on ${r.authFailures}/${r.scanned} PRs with 0 forward progress — shared Forgejo token likely revoked/expired`,
              ),
              alertId: "auto-merge-auth-failure",
              tenant: runtimeEnv.BOB_TENANT_ID
                ? { tenantId: String(runtimeEnv.BOB_TENANT_ID) }
                : undefined,
            };
            console.error(
              "[auto-merge] AUTH FAILURE — dispatch loop is dead",
              buildFailurePayload(failure),
            );
            Sentry.withScope((scope) => {
              scope.setLevel("error");
              scope.setTags(getFailureSentryTags(failure));
              scope.setContext("failure", buildFailurePayload(failure));
              Sentry.captureException(failure.error);
            });
          }
        }
      });
      ctx.waitUntil(work);
      await work;
    },
    fetch: wrapFetch(
      async (
        request: Request,
        rawEnv: Record<string, unknown> | undefined,
        ctx,
      ): Promise<Response> => {
        const url = new URL(request.url);
        const runtimeEnv = (rawEnv ?? {}) as Env;
        applyRuntimeAuthEnv(runtimeEnv);

        // WebSocket proxy to gateway — forward upgrade to origin
        if (
          url.pathname === "/ws/sessions" &&
          request.headers.get("Upgrade") === "websocket"
        ) {
          const gatewayOrigin =
            runtimeEnv.GATEWAY_URL ||
            process.env.GATEWAY_URL ||
            "https://ws.blder.bot";
          const target = `${gatewayOrigin}/sessions${url.search}`;
          return fetch(target, request);
        }

        // Image optimization via Cloudflare Images binding.
        if (url.pathname === "/_vinext/image") {
          if (!runtimeEnv.ASSETS || !runtimeEnv.IMAGES) {
            return new Response(
              "Image optimization is unavailable in this runtime",
              { status: 503 },
            );
          }
          const allowedWidths = [
            ...DEFAULT_DEVICE_SIZES,
            ...DEFAULT_IMAGE_SIZES,
          ];
          return handleImageOptimization(
            request,
            {
              fetchAsset: (path) =>
                runtimeEnv.ASSETS.fetch(
                  new Request(new URL(path, request.url)),
                ),
              transformImage: async (body, { width, format, quality }) => {
                const result = await runtimeEnv.IMAGES.input(body)
                  .transform(width > 0 ? { width } : {})
                  .output({ format, quality });
                return result.response();
              },
            },
            allowedWidths,
          );
        }

        // Expose secrets to server-side code via globalThis.
        const nudgeSecret =
          runtimeEnv.NUDGE_SHARED_SECRET ?? process.env.NUDGE_SHARED_SECRET;
        if (nudgeSecret) {
          (globalThis as any).NUDGE_SHARED_SECRET = nudgeSecret;
        }

        // Run vinext with a request-scoped DB client.
        const { connectionString, isHyperdrive } =
          getHyperdriveConnectionString(runtimeEnv);
        return runWithDb(connectionString, isHyperdrive, () =>
          handler.fetch(request, runtimeEnv, ctx),
        );
      },
    ),
  },
);
